          "text": "def transform(grid):\n    h, w = len(grid), len(grid[0])\n    # A uniform, non-background line separates two panels. Keep their cellwise overlap.\n    div_row = next((r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0), None)\n    if div_row is not None:\n        a, b = grid[:div_row], grid[div_row+1:]\n        return [[2 if x != 0 and y != 0 else 0 for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]\n    div_col = next((c for c in range(w) if all(grid[r][c] == grid[0][c] != 0 for r in range(h))), None)\n    if div_col is None:\n        raise ValueError('no separator')\n    a, b = [row[:div_col] for row in grid], [row[div_col+1:] for row in grid]\n    width = min(div_col, w-div_col-1)\n    return [[2 if a[r][c] != 0 and b[r][c] != 0 else 0 for c in range(width)] for r in range(h)]\n"
